package cli

import (
	"fmt"
	"io"
	"math"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/charmbracelet/lipgloss"
)

type statsStyles struct {
	colorEnabled bool
	width        int

	bold    lipgloss.Style
	dim     lipgloss.Style
	label   lipgloss.Style
	value   lipgloss.Style
	unit    lipgloss.Style
	desc    lipgloss.Style
	repoNm  lipgloss.Style
	commitH lipgloss.Style
	commitM lipgloss.Style
	add     lipgloss.Style
	del     lipgloss.Style
	muted   lipgloss.Style
}

func newStatsStyles(w io.Writer) statsStyles {
	useColor := shouldUseColor(w)
	width := getTerminalWidth(w)

	s := statsStyles{
		colorEnabled: useColor,
		width:        width,
	}

	if useColor {
		s.bold = lipgloss.NewStyle().Bold(true)
		s.dim = lipgloss.NewStyle().Faint(true)
		s.label = lipgloss.NewStyle().Foreground(lipgloss.Color("8")).Bold(true)
		s.value = lipgloss.NewStyle().Bold(true)
		s.unit = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))
		s.desc = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))
		s.repoNm = lipgloss.NewStyle().Foreground(lipgloss.Color("7"))
		s.commitH = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))
		s.commitM = lipgloss.NewStyle().Bold(true)
		s.add = lipgloss.NewStyle().Foreground(lipgloss.Color("2"))
		s.del = lipgloss.NewStyle().Foreground(lipgloss.Color("1"))
		s.muted = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))
	}

	return s
}

func (s statsStyles) render(style lipgloss.Style, text string) string {
	if !s.colorEnabled {
		return text
	}
	return style.Render(text)
}

func (s statsStyles) renderAgent(agentID, text string) string {
	if !s.colorEnabled {
		return text
	}
	display := agentDisplayMap[agentID]
	return lipgloss.NewStyle().Foreground(lipgloss.Color(display.Color)).Render(text)
}

type agentDisplay struct {
	Label string
	Color string // ANSI 256 color code
	Char  rune   // block character for bar charts
}

var agentDisplayMap = map[string]agentDisplay{
	"claude":   {Label: "Claude Code", Color: "208", Char: '█'},
	"gemini":   {Label: "Gemini", Color: "141", Char: '█'},
	"amp":      {Label: "Amp", Color: "219", Char: '█'},
	"codex":    {Label: "Codex", Color: "75", Char: '█'},
	"opencode": {Label: "OpenCode", Color: "37", Char: '█'},
	"copilot":  {Label: "Copilot", Color: "117", Char: '█'},
	"pi":       {Label: "Pi", Color: "204", Char: '█'},
	"cursor":   {Label: "Cursor", Color: "114", Char: '█'},
	"droid":    {Label: "Droid", Color: "215", Char: '█'},
	"kiro":     {Label: "Kiro", Color: "222", Char: '█'},
	"unknown":  {Label: "Unknown", Color: "245", Char: '░'},
}

var agentOrder = []string{
	"claude", "codex", "gemini", "amp", "opencode",
	"copilot", "pi", "cursor", "droid", "kiro", "unknown",
}

func renderStats(w io.Writer, sty statsStyles, stats contributionStats, repos []repoContribution, days []commitDay) {
	fmt.Fprintln(w)
	renderStatCards(w, sty, stats)
	fmt.Fprintln(w)
	renderAgentBreakdown(w, sty, repos)
	fmt.Fprintln(w)
	renderRepoChart(w, sty, repos)
	fmt.Fprintln(w)
	renderCommitList(w, sty, days)
}

func renderStatCards(w io.Writer, sty statsStyles, stats contributionStats) {
	cards := []struct {
		label string
		value string
		unit  string
		desc  string
	}{
		{"THROUGHPUT", fmt.Sprintf("%.1f", stats.Throughput), "k", "Avg. tokens/checkpoint"},
		{"ITERATION", fmt.Sprintf("%.1f", stats.Iteration), "x", "Avg steps/checkpoint"},
		{"CONTINUITY", fmt.Sprintf("%.1f", stats.ContinuityH), "h", "Peak session length"},
		{"STREAK", strconv.Itoa(stats.Streak), " day", fmt.Sprintf("%d current", stats.CurrentStreak)},
	}

	cardWidth := (sty.width - 3) / 4 // 3 separators
	if cardWidth < 16 {
		cardWidth = 16
	}

	var topParts, midParts, botParts []string
	for _, c := range cards {
		lbl := padOrTruncate(c.label, cardWidth)
		dsc := padOrTruncate(c.desc, cardWidth)

		topParts = append(topParts, sty.render(sty.label, lbl))
		midParts = append(midParts, sty.render(sty.value, c.value)+sty.render(sty.unit, c.unit)+
			strings.Repeat(" ", max(0, cardWidth-len(c.value)-len(c.unit))))
		botParts = append(botParts, sty.render(sty.desc, dsc))
	}

	sep := sty.render(sty.dim, " │ ")
	fmt.Fprintln(w, strings.Join(topParts, sep))
	fmt.Fprintln(w, strings.Join(midParts, sep))
	fmt.Fprintln(w, strings.Join(botParts, sep))
}

func renderAgentBreakdown(w io.Writer, sty statsStyles, repos []repoContribution) {
	agentTotals := make(map[string]int)
	total := 0
	for _, r := range repos {
		total += r.Total
		for agent, count := range r.Agents {
			agentTotals[agent] += count
		}
	}

	if total == 0 {
		return
	}

	var parts []string
	for _, id := range agentOrder {
		count, ok := agentTotals[id]
		if !ok || count == 0 {
			continue
		}
		pct := float64(count) / float64(total) * 100
		display := agentDisplayMap[id]
		parts = append(parts, sty.renderAgent(id, fmt.Sprintf("● %s %d%%", display.Label, int(math.Round(pct)))))
	}

	fmt.Fprintf(w, "%s  %s\n",
		sty.render(sty.label, "CONTRIBUTIONS"),
		sty.render(sty.muted, fmt.Sprintf("%d checkpoints", total)))
	fmt.Fprintln(w, strings.Join(parts, sty.render(sty.dim, "  ")))
}

func renderRepoChart(w io.Writer, sty statsStyles, repos []repoContribution) {
	if len(repos) == 0 {
		return
	}

	fmt.Fprintln(w, sty.render(sty.label, "REPOSITORIES"))

	maxRepos := 5
	if len(repos) < maxRepos {
		maxRepos = len(repos)
	}
	display := repos[:maxRepos]

	maxCount := display[0].Total

	maxNameLen := 0
	for _, r := range display {
		if len(r.Repo) > maxNameLen {
			maxNameLen = len(r.Repo)
		}
	}
	if maxNameLen > 30 {
		maxNameLen = 30
	}

	countWidth := len(strconv.Itoa(maxCount))
	barWidth := sty.width - maxNameLen - countWidth - 4
	if barWidth < 10 {
		barWidth = 10
	}

	for _, r := range display {
		name := r.Repo
		if len(name) > maxNameLen {
			name = name[:maxNameLen-1] + "…"
		}
		name = fmt.Sprintf("%-*s", maxNameLen, name)

		bar := renderAgentBar(sty, r.Agents, maxCount, barWidth)
		count := fmt.Sprintf("%*d", countWidth, r.Total)

		fmt.Fprintf(w, "%s %s %s\n",
			sty.render(sty.repoNm, name),
			bar,
			sty.render(sty.muted, count))
	}
}

func renderAgentBar(sty statsStyles, agents map[string]int, maxCount, barWidth int) string {
	if maxCount == 0 {
		return strings.Repeat(" ", barWidth)
	}

	var b strings.Builder

	filled := 0
	for _, id := range agentOrder {
		count, ok := agents[id]
		if !ok || count == 0 {
			continue
		}
		segWidth := int(math.Round(float64(count) / float64(maxCount) * float64(barWidth)))
		if segWidth < 1 && count > 0 {
			segWidth = 1
		}
		if filled+segWidth > barWidth {
			segWidth = barWidth - filled
		}
		if segWidth <= 0 {
			continue
		}

		display := agentDisplayMap[id]
		seg := strings.Repeat(string(display.Char), segWidth)
		b.WriteString(sty.renderAgent(id, seg))
		filled += segWidth
	}

	if filled < barWidth {
		b.WriteString(sty.render(sty.dim, strings.Repeat("░", barWidth-filled)))
	}

	return b.String()
}

package cli

import (
	"context"
	"fmt"
	"io"
	"sort"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/spf13/cobra"
	"golang.org/x/sync/errgroup"
)

const (
	agentUnknown   = "unknown"
	dateUnknown    = "unknown"
	statsTimeframe = "last-month"
	statsLimit     = 500
)

// knownAgents maps normalized agent strings from the API to display IDs.
// This is intentionally broader than agent.AgentType constants because
// the API returns agents that may not have CLI integrations (amp, pi, kiro).
var knownAgents = map[string]string{
	"claude":     "claude",
	"claudecode": "claude",
	"gemini":     "gemini",
	"geminicli":  "gemini",
	"amp":        "amp",
	"codex":      "codex",
	"opencode":   "opencode",
	"copilot":    "copilot",
	"copilotcli": "copilot",
	"pi":         "pi",
	"cursor":     "cursor",
	"droid":      "droid",
	"kiro":       "kiro",
}

func newStatsCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "stats",
		Short: "Show your activity overview",
		Long:  "Display checkpoint stats, repository breakdown, and recent commits from entire.io",
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runStats(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr())
		},
	}
	return cmd
}

func runStats(ctx context.Context, w, errW io.Writer) error {
	client, err := NewAuthenticatedAPIClient(false)
	if err != nil {
		fmt.Fprintln(errW, "Not logged in. Run 'entire login' to authenticate.")
		return NewSilentError(err)
	}

	var checkpoints []userCheckpoint
	var streakDates []string
	var commits []userCommit

	g, gCtx := errgroup.WithContext(ctx)
	g.Go(func() error {
		var fetchErr error
		checkpoints, streakDates, fetchErr = fetchCheckpoints(gCtx, client)
		return fetchErr
	})
	g.Go(func() error {
		var fetchErr error
		commits, fetchErr = fetchCommits(gCtx, client)
		return fetchErr
	})
	if err := g.Wait(); err != nil {
		return fmt.Errorf("fetch stats: %w", err)
	}

	stats := computeContributionStats(checkpoints, streakDates)
	repos := computeRepoContributions(checkpoints)
	days := groupCommitsByDay(commits)

	sty := newStatsStyles(w)
	renderStats(w, sty, stats, repos, days)

	return nil
}

func fetchCheckpoints(ctx context.Context, client *api.Client) ([]userCheckpoint, []string, error) {
	path := fmt.Sprintf("/api/v1/stats/checkpoints?timeframe=%s&limit=%d", statsTimeframe, statsLimit)
	resp, err := client.Get(ctx, path)
	if err != nil {
		return nil, nil, fmt.Errorf("GET checkpoints: %w", err)
	}
	defer resp.Body.Close()

	if err := api.CheckResponse(resp); err != nil {
		return nil, nil, fmt.Errorf("checkpoints response: %w", err)
	}

	var result userCheckpointsResponse
	if err := api.DecodeJSON(resp, &result); err != nil {
		return nil, nil, fmt.Errorf("decode checkpoints: %w", err)
	}
	return result.Checkpoints, result.StreakDates, nil
}

func fetchCommits(ctx context.Context, client *api.Client) ([]userCommit, error) {
	path := fmt.Sprintf("/api/v1/stats/commits?timeframe=%s&limit=%d", statsTimeframe, statsLimit)
	resp, err := client.Get(ctx, path)
	if err != nil {
		return nil, fmt.Errorf("GET commits: %w", err)
	}
	defer resp.Body.Close()

	if err := api.CheckResponse(resp); err != nil {
		return nil, fmt.Errorf("commits response: %w", err)
	}

	var result userCommitsResponse
	if err := api.DecodeJSON(resp, &result); err != nil {
		return nil, fmt.Errorf("decode commits: %w", err)
	}
	return result.Commits, nil
}

// computeContributionStats mirrors the frontend's computeStats + computeStreaks.
func computeContributionStats(checkpoints []userCheckpoint, streakDates []string) contributionStats {
	stats := contributionStats{}
	if len(checkpoints) == 0 {
		return stats
	}

	stats.Tasks = len(checkpoints)

	var tokenSum, tokenCount, sessionSum, maxSteps int
	for _, cp := range checkpoints {
		if cp.InputTokens != nil || cp.OutputTokens != nil {
			tokenSum += derefOr(cp.InputTokens, 0) + derefOr(cp.OutputTokens, 0)
			tokenCount++
		}
		sessionSum += derefOr(cp.SessionCount, 1)
		if s := derefOr(cp.Steps, 1); s > maxSteps {
			maxSteps = s
		}
	}

	if tokenCount > 0 {
		stats.Throughput = float64(tokenSum) / float64(tokenCount) / 1000.0
	}
	stats.Iteration = float64(sessionSum) / float64(len(checkpoints))
	// 2 min/step is the frontend's heuristic for turn duration
	stats.ContinuityH = float64(maxSteps) * 2.0 / 60.0
	stats.Streak, stats.CurrentStreak = computeStreaks(streakDates)

	return stats
}

func computeStreaks(timestamps []string) (longest, current int) {
	if len(timestamps) == 0 {
		return 0, 0
	}

	dateSet := make(map[string]struct{})
	for _, ts := range timestamps {
		t, err := parseFlexibleTime(ts)
		if err != nil {
			continue
		}
		dateSet[t.Local().Format("2006-01-02")] = struct{}{}
	}

	if len(dateSet) == 0 {
		return 0, 0
	}

	// Current streak: from today or yesterday backward
	today := time.Now().Local().Format("2006-01-02")
	check := time.Now().Local()
	if _, ok := dateSet[today]; !ok {
		check = check.AddDate(0, 0, -1)
	}
	for {
