func runStats(ctx context.Context, w, errW io.Writer) error {
	client, err := NewAuthenticatedAPIClient(false)
	if err != nil {
		fmt.Fprintln(errW, "Not logged in. Run 'entire login' to authenticate.")
		return NewSilentError(err)
	}

