func fetchCheckpoints(ctx context.Context, client *api.Client) ([]userCheckpoint, []string, error) {
	path := fmt.Sprintf("/api/v1/stats/checkpoints?timeframe=%s&limit=%d", statsTimeframe, statsLimit)
