   362	func formatCommitDate(dateStr string) string {
   363		t, err := time.Parse("2006-01-02", dateStr)
   364		if err != nil {
   365			return dateStr
   366		}
   367		now := time.Now().Local()
   368		today := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, now.Location())
   369		d := today.Sub(t)
   370	
   371		switch {
   372		case d < 24*time.Hour:
   373			return t.Format("Monday 2 Jan") + " (today)"
   374		case d < 48*time.Hour:
   375			return t.Format("Monday 2 Jan") + " (yesterday)"
   376		default:
   377			return t.Format("Monday 2 Jan")
   378		}
   379	}
